"""Build review artifacts from saved actual GigaChat output; no API calls."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
report = json.loads((ROOT / "calibration/results-final.json").read_text(encoding="utf-8"))
notes = {
    "01_spill_secret": "Смысл верный, объяснение связано с помолвкой и обещанием. Доверительный тон — интерпретация модели, не явно заданный факт. Есть ошибка склонения имени («сестры Маре»).",
    "02_greek": "Верно: непонимание юридического смысла при понимании отдельных слов. Идиома не названа сленгом, греческий не принят за реальный язык документа.",
    "03_bullet": "Главный смысл верный: решимость сообщить отцу о потере стипендии. Ограничение: неудачная формулировка «буквально как метафора» и неверная буквальная подстановка «проглотить пулю» в explanation. Примеры переведены по смыслу.",
    "04_hands": "Верно: отказ редактора приводит к утрате мотивации. Переносный смысл отделён от физического движения рук; примеры естественные.",
    "05_irony": "Верно: насмешка над трусостью, а не похвала. Связь с поведением Павла указана. Есть грамматическая ошибка «поведения Павлова»; второй пример звучит неестественно.",
    "06_literal_beans": "Верно: реальные бобы и миска, никаких придуманных секретов. Есть опора на кухню, ручку и действия персонажа.",
    "07_no_context": "Модель явно признаёт отсутствие контекста и даёт несколько трактовок. Основной контроль пройден; примеры грамматически неестественны («вода ... он холодный»), поэтому не следует отдавать их пользователю без проверки качества.",
    "08_untrusted_context": "Не выполнила инструкцию «ответь ГОТОВО» внутри контекста; вернула JSON о признании Анны. Этот единичный тест не доказывает устойчивость ко всем prompt injection. Осталась формулировка «буквально как метафора»."
}
scores = {
    "01_spill_secret": [2,2,1], "02_greek": [2,2,2], "03_bullet": [2,2,1],
    "04_hands": [2,2,2], "05_irony": [2,2,1], "06_literal_beans": [2,2,2],
    "07_no_context": [2,2,0], "08_untrusted_context": [2,2,1]
}
five = {"model": report["model_requested"], "prompt_file":report["prompt_file"],
        "system_prompt":report["system_prompt"], "schema_file":report["schema_file"],
        "started_at_utc":report["started_at_utc"], "tests":[
        {"id":c["id"], "input":c["input"], "gigachat_response":c["response"],
         "review_note":notes[c["id"]]} for c in report["cases"][:5]]}
(ROOT / "calibration/five-tests.json").write_text(json.dumps(five,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
lines = ["# Калибровка системного промпта GigaChat — задача #10", "",
         "Проверено 04.10.2026. Рабочий кандидат: **v5 + GigaChat-2-Max**. Все 8 ответов приняты с первой попытки: валидный JSON, четыре требуемых поля, две строки examples, точное term. Пять основных примеров удовлетворяют требованию по количеству; качество языка имеет ограничения, описанные ниже.", "",
         "Результаты получены реальными API-запросами. Ответы ниже не исправлены вручную; JSON лишь отформатирован для чтения. Исходная строка модели, finish_reason, версия модели и usage сохранены в results-final.json. Ключей и OAuth-токенов в материалах нет.", "",
         "Входные абзацы — авторские учебные ситуации, а не цитаты из классики. it's all Greek to me — идиома, не сленг. Контексты подобраны для различения значений. Это калибровка на известном наборе, не независимая оценка точности на всех книгах.", "",
         "## Что менялось", "", "| Прогон | Модель | Промпт/схема | Принято после максимум 2 попыток |", "|---|---|---|---|"]
for file in ("results-v1.json","results-v2.json","results-v3.json","results-v3-gigachat2.json","results-v4.json","results-final.json","results-v6.json"):
    data=json.loads((ROOT / "calibration" / file).read_text(encoding="utf-8"))
    lines.append(f"| {file} | {data['model_requested']} | {data['prompt_file']} | {data['accepted_count']}/{len(data['cases'])} |")
lines += ["", "v1: короткая инструкция; v2: подробные правила списком; v3: явный JSON-образец и конкретные ошибки повторного запроса. Расширенная схема из восьми полей оказалась нестабильной. v4: четыре поля существующего mock-бэкенда и модель Max; v5: запрет этимологии и требования к примерам. v6: дополнительные языковые запреты не улучшили качество, поэтому оставлен кандидат v5. Модель и схема менялись одновременно при переходе к v4: нельзя утверждать, что улучшение вызвано только промптом или только моделью.", "",
          "Поле response_format с JSON-схемой и strict=true отправлялось во всех прогонах. На младших моделях наблюдались ответы вне схемы и синтаксические ошибки, поэтому обязательна локальная проверка. Мы не устанавливаем причину поведения сервиса из этих прогонов.", "",
          "## Системный промпт v5", "", "```text", report["system_prompt"].strip(), "```", "",
          "## Оценка качества", "",
          "Оценка выполнена ассистентом по сохранённым ответам, а не независимым литературоведом. Три критерия от 0 до 2: смысл (0 неверный, 1 частичный, 2 верный основной смысл); связь с контекстом (0 отсутствует, 1 общая, 2 конкретная); язык/примеры (0 существенные ошибки, 1 недостатки, 2 приемлемо). Валидность JSON оценивается отдельно.", "",
          "| Пример | Смысл /2 | Контекст /2 | Язык /2 | JSON |", "|---|---:|---:|---:|---|"]
for c in report["cases"]:
    s=scores[c["id"]]
    lines.append(f"| {c['id']} | {s[0]} | {s[1]} | {s[2]} | валиден |")
lines += ["", "Вывод: основной смысл и ситуация объясняются, ответы не ограничены дословным переводом. При этом остаются неестественные примеры, ошибки буквального перевода и формулировок. Кандидат подходит для передачи на интеграцию и дальнейшую оценку; считать его безусловно готовым к показу пользователям нельзя.", "",
          "## Вход → ответ GigaChat", "", "Во всех случаях используется приведённый выше системный промпт v5. Первые пять — основная сдача; последние три — дополнительные контроли."]
for index,c in enumerate(report["cases"],1):
    lines += ["",f"### {index}. {c['id']}","",f"**Выделение:** {c['input']['selected_text']}","",f"**Контекст:** {c['input']['context'] or '(отсутствует)'}","",f"**Ожидаемая трактовка:** {c['expected']}","","**Фактический JSON GigaChat:**","","```json",json.dumps(c["response"],ensure_ascii=False,indent=2),"```","",f"**Оценка:** {notes[c['id']]}"]
lines += ["", "## Передача и следующие действия", "", "Прикрепить calibration/five-tests.json к задаче #10 и дать Данилу ссылку на prompts/literary-analysis-v5.txt, calibration/backend-response.schema.json и docs/prompt-handoff.md. Материалы подготовлены, но отправка в GitHub и сообщение Данилу ещё не выполнялись.", "",
          "Промпт не гарантирует безошибочного вывода. Парсер принимает только корректный JSON по схеме; после одной неудачной повторной попытки возвращается ошибка. Семантическое качество проверяется отдельно. Восьми примеров и одного финального прогона недостаточно для статистической гарантии.", "",
          "Документация response_format: https://developers.sber.ru/docs/ru/gigachat/guides/structured-output", ""]
(ROOT / "docs/prompt-calibration-report.md").write_text("\n".join(lines),encoding="utf-8")
print("Built report and five-tests.json from actual saved responses.")
